#include <cstddef>
#include <stdexcept>
#include <algorithm>

class Matrix {
private:
    double* data_;
    int rows_;
    int cols_;

    void allocate() {
        data_ = new double[rows_ * cols_];
        for (int i = 0; i < rows_ * cols_; ++i) {
            data_[i] = 0.0;
        }
    }

    void deallocate() {
        delete[] data_;
    }

    void copyFrom(const Matrix& other) {
        rows_ = other.rows_;
        cols_ = other.cols_;
        allocate();
        for (int i = 0; i < rows_ * cols_; ++i) {
            data_[i] = other.data_[i];
        }
    }

    void moveFrom(Matrix& other) noexcept {
        data_ = other.data_;
        rows_ = other.rows_;
        cols_ = other.cols_;
        other.data_ = nullptr;
        other.rows_ = 0;
        other.cols_ = 0;
    }

public:
    Matrix(int rows, int cols) : data_(nullptr), rows_(rows), cols_(cols) {
        if (rows <= 0 || cols <= 0) {
            throw std::invalid_argument("Rows and columns must be positive");
        }
        allocate();
    }

    ~Matrix() {
        deallocate();
    }

    Matrix(const Matrix& other) : data_(nullptr), rows_(0), cols_(0) {
        copyFrom(other);
    }

    Matrix(Matrix&& other) noexcept : data_(nullptr), rows_(0), cols_(0) {
        moveFrom(other);
    }

    Matrix& operator=(const Matrix& other) {
        if (this != &other) {
            deallocate();
            copyFrom(other);
        }
        return *this;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            deallocate();
            moveFrom(other);
        }
        return *this;
    }

    double& at(int r, int c) {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Index out of range");
        }
        return data_[r * cols_ + c];
    }

    double at(int r, int c) const {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Index out of range");
        }
        return data_[r * cols_ + c];
    }

    int rows() const {
        return rows_;
    }

    int cols() const {
        return cols_;
    }

    Matrix operator+(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            throw std::invalid_argument("Matrix dimensions must match for addition");
        }
        Matrix result(rows_, cols_);
        for (int i = 0; i < rows_ * cols_; ++i) {
            result.data_[i] = data_[i] + o.data_[i];
        }
        return result;
    }

    Matrix operator*(const Matrix& o) const {
        if (cols_ != o.rows_) {
            throw std::invalid_argument("Matrix dimensions mismatch for multiplication");
        }
        Matrix result(rows_, o.cols_);
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < o.cols_; ++j) {
                double sum = 0.0;
                for (int k = 0; k < cols_; ++k) {
                    sum += data_[i * cols_ + k] * o.data_[k * o.cols_ + j];
                }
                result.data_[i * o.cols_ + j] = sum;
            }
        }
        return result;
    }

    bool operator==(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            return false;
        }
        for (int i = 0; i < rows_ * cols_; ++i) {
            if (data_[i] != o.data_[i]) {
                return false;
            }
        }
        return true;
    }
};
